def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for x in row:
            counts[x] = counts.get(x, 0) + 1
    background = max(counts, key=counts.get)

    # Locate the solid divider, ignoring any solid line in the background color.
    div_row = next((r for r in range(h)
                    if len(set(grid[r])) == 1 and grid[r][0] != background), None)
    div_col = next((c for c in range(w)
                    if len({grid[r][c] for r in range(h)}) == 1
                    and grid[0][c] != background), None)

    if div_col is not None:
        left = [row[:div_col] for row in grid]
        right = [row[div_col + 1:] for row in grid]
        pairs = [(left[r][c], right[r][c])
                 for r in range(h) for c in range(len(left[0]))]
    else:
        top = grid[:div_row]
        bottom = grid[div_row + 1:]
        pairs = [(top[r][c], bottom[r][c])
                 for r in range(len(top)) for c in range(w)]

    matches = {}
    for a, b in pairs:
        if a == b:
            matches[a] = matches.get(a, 0) + 1
    color = max(matches, key=matches.get)

    if div_col is not None:
        return [[3 if left[r][c] == color and right[r][c] == color else color
                 for c in range(len(left[0]))] for r in range(h)]
    return [[3 if top[r][c] == color and bottom[r][c] == color else color
             for c in range(w)] for r in range(len(top))]
